def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p = (y+dy, x+dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p)
                        stack.append(p)
            if r < 5 and c < 5:
                dr, dc = 6, 0
            elif r < 5 and c >= 5:
                dr, dc = 5, -1
            elif r >= 5 and c < 5:
                dr, dc = 9 - max(y for y, x in cells), 3
            else:
                dr, dc = -3, -6
            for y, x in cells:
                yy, xx = y+dr, x+dc
                if 0 <= yy < h and 0 <= xx < w:
                    out[yy][xx] = color
    return out
